      "const capacity = 9; const joined = 8; const minAge = 18; const seaAge = 18; const seaBanned = false; const tonAge = 17; const tonBanned = false; const fonAge = 25; const fonBanned = true;\nconsole.log(\"ซี: \" + (joined < capacity && seaAge >= minAge ? \"เข้าร่วมได้\" : \"เข้าร่วมไม่ได้\")); console.log(\"ต้น: \" + (joined < capacity && tonAge >= minAge ? \"เข้าร่วมได้\" : \"เข้าร่วมไม่ได้\")); console.log(\"ฝน: \" + (joined < capacity && fonAge >= minAge ? \"เข้าร่วมได้\" : \"เข้าร่วมไม่ได้\"));",
      "const capacity = 9; const joined = 8; const minAge = 18; const seaAge = 18; const seaBanned = false; const tonAge = 17; const tonBanned = false; const fonAge = 25; const fonBanned = true;\nconsole.log(\"ซี: \" + (joined < capacity || seaAge >= minAge && !seaBanned ? \"เข้าร่วมได้\" : \"เข้าร่วมไม่ได้\")); console.log(\"ต้น: \" + (joined < capacity || tonAge >= minAge && !tonBanned ? \"เข้าร่วมได้\" : \"เข้าร่วมไม่ได้\")); console.log(\"ฝน: \" + (joined < capacity || fonAge >= minAge && !fonBanned ? \"เข้าร่วมได้\" : \"เข้าร่วมไม่ได้\"));",
