  starter: "function costPerPerson(total, people, tipPercent) {\n  // 1) ถ้าจำนวนคนเป็นไปไม่ได้ ให้คืน null\n  // 2) คำนวณยอดรวมทิป\n  // 3) หารแล้วปัดขึ้น\n  return 0;\n}\n\nconsole.log(costPerPerson(1000, 4, 10)); // ควรได้ 275",
  solution: "function costPerPerson(total, people, tipPercent) {\n  if (people <= 0) return null;\n  const tip = total * tipPercent / 100;\n  const grandTotal = total + tip;\n  return Math.ceil(grandTotal / people);\n}",
