      "function addMember(activity, name) { return { ...activity, members: [...activity.members, name] }; }\nfunction checkAddMember(activity, name) { const updated = addMember(activity, name); return { originalMembers: activity.members, updatedMembers: updated.members, sameObject: updated === activity }; }",
