  tracePrompt: "ก่อนรัน: เขียน output ที่คาดไว้ แล้วอธิบายว่าทำไม seatsLeft ใช้ Math.max(0, ...) ข้อมูลแบบไหนจะทำให้ค่าติดลบถ้าไม่ใส่",
  traceAnswer: "{\"fullCount\":1,\"seatsLeft\":2} — Hiking เต็ม (8 ≥ 8) ที่นั่งเหลือ 0 + 2 = 2 Math.max(0, ...) กันกรณีข้อมูลผิดที่ joined มากกว่า capacity เช่น joined 10 capacity 8 จะได้ −2 และทำให้ยอดรวมน้อยกว่าความจริง",
  practicePrompt: "เขียน summarizePlanner(activities) ที่คืน { total, open, full, seatsLeft, topTitle } โดย open/full คือจำนวนกิจกรรมที่ยังรับคน/เต็มแล้ว seatsLeft คือที่นั่งว่างรวม (ไม่ติดลบ) และ topTitle คือชื่อกิจกรรมคะแนนโหวตสูงสุด (เท่ากันเลือกชื่อตามตัวอักษร) ถ้าไม่มีกิจกรรมให้ topTitle เป็น null",
  starter: "function isFull(activity) {\n  // กิจกรรมเต็มเมื่อไร? (ระวังข้อมูลที่ joined เกิน capacity)\n  return false;\n}\n\nfunction summarizePlanner(activities) {\n  // แตกเป็น helper ทีละ field แล้วประกอบ\n  return { total: activities.length, open: 0, full: 0, seatsLeft: 0, topTitle: null };\n}",
  solution: "function isFull(activity) {\n  return activity.joined >= activity.capacity;\n}\n\nfunction topActivityTitle(activities) {\n  if (activities.length === 0) return null;\n  const ranked = [...activities].sort((a, b) => b.votes - a.votes || a.title.localeCompare(b.title));\n  return ranked[0].title;\n}\n\nfunction summarizePlanner(activities) {\n  const full = activities.filter(isFull).length;\n  const seatsLeft = activities.reduce((sum, activity) => sum + Math.max(0, activity.capacity - activity.joined), 0);\n  return {\n    total: activities.length,\n    open: activities.length - full,\n    full,\n    seatsLeft,\n    topTitle: topActivityTitle(activities),\n  };\n}",
  autoCheck: {
    functionName: "summarizePlanner",
    tests: [
      { name: "ข้อมูลปกติ", args: [[{ title: "Hiking", capacity: 8, joined: 8, votes: 5 }, { title: "Board game", capacity: 6, joined: 4, votes: 9 }, { title: "Cafe hop", capacity: 5, joined: 1, votes: 2 }]], expected: { total: 3, open: 2, full: 1, seatsLeft: 6, topTitle: "Board game" } },
      { name: "โหวตเท่ากันเลือกตามชื่อ", args: [[{ title: "Movie", capacity: 4, joined: 1, votes: 7 }, { title: "Karaoke", capacity: 4, joined: 2, votes: 7 }]], expected: { total: 2, open: 2, full: 0, seatsLeft: 5, topTitle: "Karaoke" } },
      { name: "joined เกิน capacity ไม่ทำให้ที่นั่งติดลบ", args: [[{ title: "Hiking", capacity: 8, joined: 10, votes: 1 }, { title: "Board game", capacity: 6, joined: 4, votes: 0 }]], expected: { total: 2, open: 1, full: 1, seatsLeft: 2, topTitle: "Hiking" } },
      { name: "ไม่มีกิจกรรม", args: [[]], expected: { total: 0, open: 0, full: 0, seatsLeft: 0, topTitle: null } },
    ],
    wrongAnswers: [
      "function summarizePlanner(activities) { const full = activities.filter((a) => a.joined === a.capacity).length; const seatsLeft = activities.reduce((s, a) => s + Math.max(0, a.capacity - a.joined), 0); const top = [...activities].sort((a, b) => b.votes - a.votes || a.title.localeCompare(b.title))[0]; return { total: activities.length, open: activities.length - full, full, seatsLeft, topTitle: top ? top.title : null }; }",
      "function summarizePlanner(activities) { const full = activities.filter((a) => a.joined >= a.capacity).length; const seatsLeft = activities.reduce((s, a) => s + (a.capacity - a.joined), 0); const top = [...activities].sort((a, b) => b.votes - a.votes || a.title.localeCompare(b.title))[0]; return { total: activities.length, open: activities.length - full, full, seatsLeft, topTitle: top ? top.title : null }; }",
      "function summarizePlanner(activities) { const full = activities.filter((a) => a.joined >= a.capacity).length; const seatsLeft = activities.reduce((s, a) => s + Math.max(0, a.capacity - a.joined), 0); const top = [...activities].sort((a, b) => b.votes - a.votes)[0]; return { total: activities.length, open: activities.length - full, full, seatsLeft, topTitle: top ? top.title : null }; }",
    ],
  },
