  example: "const raw = [\n  { title: \"Hiking\", day: \"sat\", time: \"07:00\" },\n  { title: \"\", day: \"sat\", time: \"09:00\" },\n  { title: \"Movie\", day: \"fri\", time: \"19:30\" },\n];\n\nconst problems = raw.filter((item) => item.title.trim() === \"\").length;\nconst byDay = {};\nfor (const item of raw) {\n  if (item.title.trim() === \"\") continue;\n  byDay[item.day] = [...(byDay[item.day] ?? []), item.title];\n}\nconsole.log(byDay, problems);",
