  practicePrompt: "เขียน planWeek(activities) ที่คืน { schedule, invalid } โดยกิจกรรมถูกต้องเมื่อ ชื่อไม่ว่างหลัง trim, day เป็นหนึ่งใน mon tue wed thu fri sat sun และ time อยู่ในรูป HH:MM (00–23 : 00–59) schedule จัดกลุ่มตาม day และเรียงตาม time ในแต่ละวัน เก็บเป็น \"HH:MM ชื่อ\" ส่วน invalid เก็บ index ของรายการที่ผิดตามลำดับเดิม",
  starter: "const DAYS = [\"mon\", \"tue\", \"wed\", \"thu\", \"fri\", \"sat\", \"sun\"];\n\nfunction isValidTime(time) {\n  // ตรวจรูปแบบ HH:MM และช่วงชั่วโมง/นาที\n  return true;\n}\n\nfunction planWeek(activities) {\n  const schedule = {};\n  const invalid = [];\n  // validate (ชื่อ, day, time) → group by day → sort by time\n  return { schedule, invalid };\n}",
  solution: "const DAYS = [\"mon\", \"tue\", \"wed\", \"thu\", \"fri\", \"sat\", \"sun\"];\n\nfunction isValidTime(time) {\n  if (!/^\\d{2}:\\d{2}$/.test(time)) return false;\n  const [hours, minutes] = time.split(\":\").map(Number);\n  return hours <= 23 && minutes <= 59;\n}\n\nfunction planWeek(activities) {\n  const schedule = {};\n  const invalid = [];\n  activities.forEach((activity, index) => {\n    if (activity.title.trim() === \"\" || !DAYS.includes(activity.day) || !isValidTime(activity.time)) {\n      invalid.push(index);\n      return;\n    }\n    schedule[activity.day] = [...(schedule[activity.day] ?? []), activity];\n  });\n  for (const day of Object.keys(schedule)) {\n    schedule[day] = [...schedule[day]]\n      .sort((a, b) => a.time.localeCompare(b.time))\n      .map((activity) => activity.time + \" \" + activity.title.trim());\n  }\n  return { schedule, invalid };\n}",
