      "const DAYS = [\"mon\", \"tue\", \"wed\", \"thu\", \"fri\", \"sat\", \"sun\"];\nfunction planWeek(activities) { const schedule = {}; const invalid = []; activities.forEach((a, i) => { if (a.title.trim() === \"\" || !DAYS.includes(a.day) || !/^\\d{2}:\\d{2}$/.test(a.time)) { invalid.push(i); return; } schedule[a.day] = [...(schedule[a.day] ?? []), a.time + \" \" + a.title.trim()]; }); return { schedule, invalid }; }",
      "function planWeek(activities) { const schedule = {}; const invalid = []; activities.forEach((a, i) => { const ok = /^\\d{2}:\\d{2}$/.test(a.time) && Number(a.time.slice(0, 2)) <= 23 && Number(a.time.slice(3)) <= 59; if (a.title.trim() === \"\" || !ok) { invalid.push(i); return; } schedule[a.day] = [...(schedule[a.day] ?? []), a]; }); for (const d of Object.keys(schedule)) schedule[d] = [...schedule[d]].sort((x, y) => x.time.localeCompare(y.time)).map((a) => a.time + \" \" + a.title.trim()); return { schedule, invalid }; }",
