  buggy: "function groupByDay(activities) {\n  const groups = {};\n  for (const activity of activities) {\n    groups[activity.day].push(activity.title);\n  }\n  return groups;\n}\n\nconsole.log(groupByDay([{ title: \"Hiking\", day: \"sat\" }]));",
